```sqlite
SELECT DISTINCT A.element FROM atom A JOIN molecule M ON A.molecule_id = M.molecule_id WHERE M.label = 'TR000' ORDER BY A.element ASC LIMIT 3;
```

```sqlite
SELECT AVG(bond_count) FROM (SELECT COUNT(b.bond_id) AS bond_count FROM atom a JOIN connected c ON a.atom_id = c.atom_id GROUP BY a.atom_id WHERE a.element = 'i') AS bond_counts;
```

```sqlite
SELECT CAST(SUM(CASE WHEN m.label = '+' AND a.element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(DISTINCT m.molecule_id) FROM molecule AS m INNER JOIN atom AS a ON m.molecule_id = a.molecule_id;
```

```sqlite
SELECT DISTINCT m.label FROM molecule AS m JOIN atom AS a ON m.molecule_id = a.molecule_id WHERE m.label = '-' GROUP BY m.molecule_id HAVING COUNT(a.atom_id) > 5;
```

```sqlite
SELECT CAST(SUM(CASE WHEN s.isOnlineOnly = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(DISTINCT st.setCode) FROM sets AS s JOIN set_translations AS st ON s.code = st.setCode WHERE st.language = 'Portuguese (Brazil)';
```

```sql
SELECT id FROM sets WHERE type = 'commander' ORDER BY totalSetSize DESC LIMIT 1;
```

```sqlite
SELECT T1.full_name FROM superhero AS T1 INNER JOIN hero_attribute AS T2 ON T1.id = T2.hero_id INNER JOIN attribute AS T3 ON T2.attribute_id = T3.id WHERE T3.attribute_name = 'strength' GROUP BY T1.id HAVING MAX(T2.attribute_value) = (SELECT MAX(attribute_value) FROM hero_attribute WHERE attribute_id = (SELECT id FROM attribute WHERE attribute_name = 'strength'));
```

```sqlite
SELECT T.team_short_name FROM Team_Attributes AS TA JOIN Team AS T ON TA.team_fifa_api_id = T.team_fifa_api_id WHERE TA.buildUpPlaySpeed IN (SELECT MAX(buildUpPlaySpeed) FROM Team_Attributes) LIMIT 4;
```
